// ─────────────────────────────────────────────────────────────
// Base d'ingrédients normalisés.
// Nutrition pour 100 g (cru, partie comestible) — valeurs moyennes
// issues des tables usuelles (Ciqual / USDA), arrondies.
// Chaque recette référence ces `id`. Ajouter un ingrédient = une ligne.
// ─────────────────────────────────────────────────────────────
import type {
  Ingredient,
  IngredientCategory,
  ProteinGroup,
  Season,
  ShoppingAisle,
  StandardUnit,
} from '../domain/types';

interface Opts {
  pl?: string; // pluriel
  al?: string[]; // alias
  u?: StandardUnit;
  pw?: number; // poids pièce (g)
  d?: number; // densité
  pg?: ProteinGroup;
  s?: Season[];
  pkg?: number;
  st?: boolean; // ingrédient de base
  fl?: Ingredient['flags'];
  e?: string;
  aisle?: ShoppingAisle;
  er?: number; // part comestible (os / coquilles)
  erw?: number; // part comestible si compté en pièces entières
}

const AISLE: Record<IngredientCategory, ShoppingAisle> = {
  viande: 'viandes-poissons',
  volaille: 'viandes-poissons',
  abats: 'viandes-poissons',
  poisson: 'viandes-poissons',
  'fruits-de-mer': 'viandes-poissons',
  oeufs: 'oeufs',
  laitier: 'laitiers',
  feculent: 'feculents',
  legume: 'legumes',
  legumineuse: 'feculents',
  fruit: 'fruits',
  herbe: 'herbes-epices',
  epice: 'herbes-epices',
  'matiere-grasse': 'epicerie',
  condiment: 'epicerie',
  epicerie: 'epicerie',
  boisson: 'epicerie',
};

const PRINT: Season[] = ['printemps'];
const ETE: Season[] = ['ete'];
const AUT: Season[] = ['automne'];
const HIV: Season[] = ['hiver'];
const PE: Season[] = ['printemps', 'ete'];
const EA: Season[] = ['ete', 'automne'];
const AH: Season[] = ['automne', 'hiver'];
const AHP: Season[] = ['automne', 'hiver', 'printemps'];

function I(
  id: string,
  name: string,
  category: IngredientCategory,
  n: [number, number, number, number],
  o: Opts = {},
): Ingredient {
  return {
    id,
    name,
    plural: o.pl,
    aliases: o.al,
    category,
    aisle: o.aisle ?? AISLE[category],
    unit: o.u ?? 'g',
    pieceWeight: o.pw,
    density: o.d,
    kcal: n[0],
    protein: n[1],
    carbs: n[2],
    fat: n[3],
    staple: o.st,
    protein_group: o.pg,
    seasons: o.s && o.s.length ? o.s : undefined,
    packageSize: o.pkg,
    flags: o.fl,
    emoji: o.e,
    edible: o.er,
    edibleWhole: o.erw,
  };
}

